        // ---- level 2: f1 = fold(m1) ----
        ap_uint<31> nf1 = p2e_fold62(m1);
        ap_uint<33> ns2[4];
        ns2[0] = alu_addp<33>(s1[0], s1[1]); ns2[1] = alu_addp<33>(s1[2], s1[3]);
        ns2[2] = alu_addp<33>(s1[4], s1[5]); ns2[3] = alu_addp<33>(s1[6], s1x);
        // ---- level 1: m1 = x0^2, pair sums, 2^s_i x_i ----
