        s3[0] = ns3[0]; s3[1] = ns3[1];
        for (int k = 0; k < 4; k++) {
#pragma HLS UNROLL
            s2[k] = ns2[k];
        }
        for (int k = 0; k < 7; k++) {
#pragma HLS UNROLL
            s1[k] = ns1[k];
        }
        s1x = x[15];
        x0[3] = x0[2]; x0[2] = x0[1]; x0[1] = x0[0]; x0[0] = x[0];
        for (int l = 7; l >= 1; l--) {
#pragma HLS UNROLL
            for (int i = 1; i < 16; i++) {
#pragma HLS UNROLL
                xr[l][i] = xr[l - 1][i];
            }
        }
        for (int i = 1; i < 16; i++) {
#pragma HLS UNROLL
            xr[0][i] = nxr[i];
        }
